35	func handleFormCancellation(w io.Writer, action string, err error) error {
36		if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, huh.ErrTimeout) ||
37			errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
38			fmt.Fprintf(w, "%s cancelled.\n", action)
39			return nil
40		}
41		return fmt.Errorf("%s prompt failed: %w", action, err)
42	}
