47	func printSessionCommand(w io.Writer, resumeCmd, prompt string, isMulti, isLast bool) {
48		comment := ""
49		if isMulti && isLast {
50			if prompt != "" {
51				comment = fmt.Sprintf("  # %s (most recent)", prompt)
52			} else {
